// EncodeOrc writes the value to w in the Orc binary format.
func (lc LabelConfig) EncodeOrc(w *orc.Writer) error {
	if lc.Label != nil {
		w.Bool(true)
		w.String(*lc.Label)
	} else {
		w.Bool(false)
	}
	if lc.Level != nil {
		w.Bool(true)
		w.String(string(*lc.Level))
	} else {
		w.Bool(false)
	}
	if lc.Orientation != nil {
		w.Bool(true)
		w.String(string(*lc.Orientation))
	} else {
		w.Bool(false)
	}
	if lc.Direction != nil {
		w.Bool(true)
		w.String(string(*lc.Direction))
	} else {
		w.Bool(false)
	}
	if lc.MaxInlineSize != nil {
		w.Bool(true)
		w.Float64(float64(*lc.MaxInlineSize))
	} else {
		w.Bool(false)
	}
	if lc.Align != nil {
		w.Bool(true)
		w.String(string(*lc.Align))
	} else {
		w.Bool(false)
	}
	return nil
}

